using UnityEngine;using LWS.TruckCheeseRolling;
namespace LWS.TruckMattressRacing {
public sealed class MattressWorld:MonoBehaviour {
 public MattressMatch match;public MattressObstacle[] obstacles;public MattressWalker[] walkers;public ParticleSystem[] blasts;public Rigidbody[] pillows;public int Explosions{get;private set;}public int PedestrianHits{get;set;}int blast;
 public void ResetPillows(){if(pillows==null)return;for(int i=0;i<pillows.Length;i++){var b=pillows[i];b.gameObject.SetActive(true);if(!b.isKinematic)b.linearVelocity=b.angularVelocity=Vector3.zero;b.isKinematic=true;b.detectCollisions=true;var racer=match.racers[i/2];var pad=racer.pad as BoxCollider;var local=new Vector3(i%2==0?-.8f:.8f,.49f,-2.18f); // two loose pillows at the mattress foot, outside the truck's rear.
   var q=racer.truck.body.rotation;var p=racer.truck.transform.TransformPoint(local);var shape=b.GetComponent<Collider>();bool found=false;for(int z=0;z<6&&!found;z++)for(int x=0;x<7&&!found;x++){var test=local+new Vector3((i%2==0?-1:1)*x*.08f,0,z*.08f);p=racer.truck.transform.TransformPoint(test);if(Mathf.Abs(test.x)+.39f>1.69f||Mathf.Abs(test.z)+.275f>2.59f)continue;if(!Physics.ComputePenetration(shape,p,q,racer.truck.shape,racer.truck.shape.transform.position,racer.truck.shape.transform.rotation,out _,out _)){found=true;local=test;}}
   if(!found){Debug.LogError("Pillow has no nonoverlapping mattress-foot placement slot="+i);p=racer.truck.transform.TransformPoint(local);}b.position=p;b.rotation=q;b.transform.SetPositionAndRotation(p,q);PaintPillow(b.GetComponent<Renderer>(),i/2);}
  if(match.replay!=null&&match.replay.ghosts.Length>8)foreach(var renderer in match.replay.ghosts[8].GetComponentsInChildren<Renderer>(true))if(renderer.name.StartsWith("Loose player pillow ")&&int.TryParse(renderer.name.Substring(20),out int i))PaintPillow(renderer,i/2);
 }
 void PaintPillow(Renderer renderer,int slot){var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",match.setup.players[slot].color);block.SetColor("_Color",match.setup.players[slot].color);renderer.SetPropertyBlock(block);}
 public void ReleasePillows(){if(pillows==null)return;foreach(var b in pillows){b.isKinematic=false;b.WakeUp();}}
 public void ResetWorld(int seed){gameObject.SetActive(true);Explosions=PedestrianHits=0;var rng=new System.Random(seed);for(int i=0;i<obstacles.Length;i++){var o=obstacles[i];float z=48+i*16.5f;float x=match.course.Center(z)+(i%2==0?-1:1)*(o.kind==MattressObstacleKind.Tree?25+(float)rng.NextDouble()*7:7+(float)rng.NextDouble()*17);var p=match.course.Surface(new Vector3(x,0,z));o.ResetObstacle(p,match.course.Rotation(z));}for(int i=0;i<walkers.Length;i++)walkers[i].ResetWalker(82+i*72);}
 public void Explode(Vector3 position){Explosions++;var fx=blasts[blast++%blasts.Length];fx.transform.position=position;fx.Play();foreach(var r in match.racers){if(r.Phase!=MattressAttempt.Racing)continue;var b=r.truck.body;var d=b.worldCenterOfMass-position;float distance=d.magnitude;if(distance>12)continue;d.y=Mathf.Max(1.2f,d.y+2);b.AddForce(d.normalized*Mathf.Lerp(9,1,distance/12),ForceMode.VelocityChange);b.AddTorque(Vector3.Cross(Vector3.up,d.normalized)*Mathf.Lerp(2,.2f,distance/12),ForceMode.VelocityChange);match.Pulse(r.slot,.3f,.16f);}foreach(var o in obstacles)if(o.tree!=null&&Vector3.Distance(o.transform.position,position)<20)o.tree.Blast(position);match.feedback.Play(7,8);}
 public void Freeze(){foreach(var o in obstacles)o.body.isKinematic=true;if(pillows!=null)foreach(var pillow in pillows)pillow.isKinematic=true;foreach(var w in walkers)w.StopWalker();foreach(var p in blasts)p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}public void Hide(){Freeze();gameObject.SetActive(false);}
 void LateUpdate(){if(!match.Live||match.Phase!=MattressPhase.Race)return;foreach(var o in obstacles)o.Maintain();foreach(var w in walkers)w.Step();}
}
public enum MattressObstacleKind{Tree,Sheep,Loose,Fence}
}
